    // ── Navigate-mode pan / anchored stretch ─────────────────────────────────
    function _clampF(f) { return Math.max(0.02, Math.min(0.98, f)); }
    function _validRange(r) { return r && isFinite(r[0]) && isFinite(r[1]) && (r[1] - r[0]) > 1e-6; }

